// Translation dictionaries. English strings ARE the keys (i18n/en.json, generated by tools/extract-strings.js).
// Lookup order: hand-written seed (i18n/seed/<lang>.json) → cache (data/i18n/<lang>.json) → AI translation of whatever is
// missing (needs ANTHROPIC_API_KEY; the result is cached so you pay once per language and can edit the cache file).
const fs = require("fs");
const path = require("path");
const { LANG_CODES } = require("./languages");
const ROOT = path.join(__dirname, "..");
const SEED_DIR = path.join(ROOT, "i18n", "seed");
const CACHE_DIR = path.join(process.env.SOKONI_DATA_DIR || path.join(ROOT, "data"), "i18n");
const readJSON = (f) => { try { return JSON.parse(fs.readFileSync(f, "utf8")); } catch { return {}; } };
const english = () => readJSON(path.join(ROOT, "i18n", "en.json"));
const aiConfigured = () => !!process.env.ANTHROPIC_API_KEY;
const langName = (code) => { try { return new Intl.DisplayNames(["en"], { type: "language" }).of(code) || code; } catch { return code; } };
const placeholders = (s) => (String(s).match(/\{\w+\}/g) || []).sort().join("|");
const inflight = {};

async function translateBatch(code, entries) {
  const prompt = `Translate the VALUES of this JSON object from English into ${langName(code)} (language code "${code}"). These are user-interface strings of a produce trading marketplace used by farmers, buyers and transport companies. Use natural, simple, polite wording. Keep the JSON keys EXACTLY unchanged. Keep every {placeholder} unchanged, and keep emoji, numbers and punctuation like ":" "…" "·". Do not translate brand names (Sokoni, M-Pesa, Incoterm codes such as FCA, currency codes). Output ONLY the JSON object, nothing else.\n\n${JSON.stringify(entries)}`;
  const r = await fetch("https://api.anthropic.com/v1/messages", { method: "POST", headers: { "Content-Type": "application/json", "x-api-key": process.env.ANTHROPIC_API_KEY, "anthropic-version": "2023-06-01", ...(process.env.ANTHROPIC_WORKSPACE_ID ? { "anthropic-workspace-id": process.env.ANTHROPIC_WORKSPACE_ID } : {}) },
    body: JSON.stringify({ model: process.env.I18N_MODEL || require("./ai").model(), max_tokens: 8000, messages: [{ role: "user", content: prompt }] }) });
  if (!r.ok) throw new Error("translation API " + r.status);
  const d = await r.json(); let text = (d.content || []).filter((c) => c.type === "text").map((c) => c.text).join("").trim();
  text = text.replace(/^```(?:json)?\s*/i, "").replace(/\s*```$/, ""); const out = JSON.parse(text); const ok = {};
  for (const k of Object.keys(entries)) if (typeof out[k] === "string" && out[k].trim() && placeholders(out[k]) === placeholders(k)) ok[k] = out[k];
  return ok;
}
async function translateMissing(code, missing) {
  const result = {}; const size = 60;
  for (let i = 0; i < missing.length; i += size) {
    const chunk = {}; missing.slice(i, i + size).forEach((k) => { chunk[k] = k; });
    Object.assign(result, await translateBatch(code, chunk));
  }
  return result;
}
async function dictionary(code) {
  if (!LANG_CODES.has(code)) return { error: "Unknown language." };
  if (code === "en") return { dict: {}, complete: true, source: "en" };
  const cacheFile = path.join(CACHE_DIR, code + ".json");
  let dict = { ...readJSON(path.join(SEED_DIR, code + ".json")), ...readJSON(cacheFile) }; let source = Object.keys(dict).length ? "seed" : "none";
  const keys = Object.keys(english()); let missing = keys.filter((k) => !(k in dict));
  if (missing.length && aiConfigured()) {
    try {
      inflight[code] = inflight[code] || translateMissing(code, missing).finally(() => { delete inflight[code]; });
      const fresh = await inflight[code];
      if (Object.keys(fresh).length) { dict = { ...dict, ...fresh }; fs.mkdirSync(CACHE_DIR, { recursive: true }); fs.writeFileSync(cacheFile, JSON.stringify({ ...readJSON(cacheFile), ...fresh }, null, 1)); source = "ai"; }
    } catch (e) { console.error("i18n translate", code, e.message); }
    missing = keys.filter((k) => !(k in dict));
  }
  return { dict, complete: missing.length === 0, source: Object.keys(dict).length ? source : "none" };
}
module.exports = { dictionary, english, aiConfigured };
